class SlowHash:
    def __init__(self, algorithm, backend=None, ctx=None):
        self._obj=orig(algorithm, backend=backend, ctx=ctx)
    def update(self, data):
        time.sleep(0.01)
        self._obj.update(data)
    def finalize(self):
        return self._obj.finalize()
    def copy(self):
        c=SlowHash.__new__(SlowHash)
        c._obj=self._obj.copy()
